  ['npm-token', /\bnpm_[A-Za-z0-9]{30,}/], // CYB-11
  ['google-api-key', /\bAIza[0-9A-Za-z_-]{30,}/], // CYB-11
  ['slack-token', /\bxox[baprs]-[A-Za-z0-9-]{10,}/],
